// Bitrix24 entrega los eventos del bot (ONIMBOTMESSAGEADD / ONIMBOTJOINCHAT)
// como application/x-www-form-urlencoded. n8n los expone en body con claves
// anidadas tipo data[PARAMS][MESSAGE]. Este nodo normaliza todo a campos planos.
const raw = $input.first().json;
const body = raw.body || raw;

function get(...paths) {
  for (const p of paths) {
    // soporta clave plana 'data[PARAMS][MESSAGE]' o navegacion por objeto
    if (body[p] !== undefined && body[p] !== null && body[p] !== '') return body[p];
  }
  return '';
}
function nav(obj, keys) {
  let cur = obj;
  for (const k of keys) { if (cur && cur[k] !== undefined) cur = cur[k]; else return ''; }
  return cur === undefined || cur === null ? '' : cur;
}

const event = get('event') || nav(body, ['event']);
const message = get('data[PARAMS][MESSAGE]') || nav(body, ['data','PARAMS','MESSAGE']);
const dialogId = get('data[PARAMS][DIALOG_ID]') || nav(body, ['data','PARAMS','DIALOG_ID']);
const chatId = get('data[PARAMS][CHAT_ID]') || nav(body, ['data','PARAMS','CHAT_ID']);
const fromUserId = get('data[PARAMS][FROM_USER_ID]') || nav(body, ['data','PARAMS','FROM_USER_ID']);
const botId = get('data[BOT][0][BOT_ID]') || nav(body, ['data','BOT']) || '';
const appToken = get('auth[application_token]') || nav(body, ['auth','application_token']);

const userName = get('data[USER][NAME]','data[USER][FULL_NAME]') || nav(body, ['data','USER','NAME']) || nav(body, ['data','USER','FULL_NAME']);
const userEmail = get('data[USER][EMAIL]') || nav(body, ['data','USER','EMAIL']);
const userPhone = get('data[USER][PHONES]','data[USER][PHONE]') || nav(body, ['data','USER','PHONES']) || nav(body, ['data','USER','PHONE']);

return [{ json: {
  event: String(event || ''),
  message: String(message || '').trim(),
  dialogId: String(dialogId || ''),
  chatId: String(chatId || ''),
  fromUserId: String(fromUserId || ''),
  botId: String(botId || ''),
  appToken: String(appToken || ''),
  userName: String(userName || ''),
  userEmail: String(userEmail || ''),
  userPhone: String(userPhone || '')
} }];

// Determina si el prospecto YA existe en el CRM y arma el system prompt
// con la logica de las misiones del bot original (Demaco / RoberthV2).
const ev = $('Parsear evento').item.json;
const crm = $input.first().json;

// crm.duplicate.findbycomm -> result.CONTACT = [ids] cuando hay coincidencia.
let contactId = '';
try {
  const r = (crm && crm.result) || {};
  const ids = r.CONTACT || r.contact || [];
  if (Array.isArray(ids) && ids.length) contactId = String(ids[0]);
} catch (e) {}
const existe = !!contactId;

// ----- Memoria de conversacion por DIALOG_ID (estado entre mensajes) -----
const store = $getWorkflowStaticData('global');
const key = 'hist_' + ev.dialogId;
const history = Array.isArray(store[key]) ? store[key] : [];

// Directorio de locales (el bot responde ubicaciones).
const locales = [
  'Guayaquil - Demaco Matriz (B2): Cjon. 2Do Cjon. 14A N-E y Psje. Francisco Illingworth, Cdla. Santa Leonor. Tel (04)606-592 / (04)606-602. ventas@demaco.ec',
  'Guayaquil - Demaco Americas (B41): Psje. 2Do Paseo 14 N-E y Av. De las Americas. Tel (04)228-9000',
  'Guayaquil - Demaco Centro (B1): Machala y Colon, C. 8 S-O. Tel (04)232-6635. ventas@demaco.ec',
  'Guayaquil - Demaco Portete (B87): Pasando la planta de Duragas, Urb. Jardines del Salado, Via a la Costa. Tel (04)287-9335. ventas@demaco.ec',
  'Quito - Demaco Quito Norte (B10): Av. Quito Norte y calle 123. Tel (02)223-2431 / 0967471632. quito@demaco.ec',
  'Quito - Demaco Quito Sur (B15): Av. Quito Sur y calle 456. Tel (02)2438737. quito@demaco.ec',
  'Ambato - Demaco Ambato Centro (B25): Av. Ambato Centro y calle 789. Tel (03)282-5866. izamba@demaco.ec',
  'Ambato - Demaco Ambato Sur (B26): Av. Ambato Sur y calle 202. Tel (03)241-9114. ambato3@demaco.ec',
  'Ambato - Demaco Ambato Norte (B23): Av. Ambato Norte y calle 101. Tel (03)285-4099. ambato2@demaco.ec',
  'Portoviejo - Demaco Portoviejo (B50): Av. Portoviejo y calle 303. Tel (05)293-4819. portoviejo@demaco.ec'
].join('\n');

const contexto = existe
  ? `El cliente YA EXISTE en el CRM (contactId=${contactId}). Mision: mantener su ficha actualizada (Nombre, Email, Telefono, Ciudad, RUC/Cedula y Razon social si es empresa). Puede saltar la actualizacion con la palabra "Saltar". Luego ayuda a capturar su requerimiento de productos.`
  : `El cliente es un PROSPECTO NUEVO (no esta en el CRM). Mision: calificarlo y capturar Nombre, si compra como persona natural o empresa, RUC/Cedula, razon social (si empresa), Telefono, Email, Ciudad y tipo de venta (B2B mayoreo / B2C consumidor final).`;

const systemPrompt = `Eres "Roberth", asistente comercial digital de DEMACO (distribuidor de ferreteria en Ecuador). Atiendes por chat (WhatsApp/Open Lines). Hablas espanol, eres amable, servicial y usas emojis con moderacion.

${contexto}

Reglas:
- Dirigete a la persona por su nombre cuando lo sepas.
- Si piden precios o cotizaciones de inmediato, explica que por politica corporativa necesitamos los datos para crear un perfil de precios, y que el precio difiere entre B2B (mayoreo/ferreteria) y B2C (proyectos/publico).
- Si preguntan disponibilidad o existencias de inventario, indica que un asesor se lo confirmara en un momento.
- Si preguntan por horarios, locales o ubicaciones, responde directamente con estos datos:
${locales}
Todas las sucursales estan en Google Maps con la palabra "Demaco".
- Para entregas a domicilio pide direccion, ciudad, geolocalizacion y contacto de quien recibe. El transporte es gratis para compras sobre $50.00.
- Si el cliente escribe "Operador" o pide hablar con una persona, transfiere a un asesor.
- Intenta recopilar la informacion en la menor cantidad de interacciones posibles. No inventes datos ni respondas fuera de tu mision.

Debes responder SIEMPRE en JSON valido con esta forma exacta (sin texto adicional):
{
  "respuesta": "texto que se enviara al cliente en el chat",
  "accion": "responder" | "crear_lead" | "actualizar_ficha" | "transferir",
  "datos": {
    "Nombre": "", "Telefono": "", "Email": "", "Ciudad": "",
    "Tipo_venta": "", "Ruc_cedula": "", "Razon_social": "",
    "Lista_productos": "", "Direccion_entrega": "", "Ciudad_entrega": "", "Contacto_entrega": ""
  }
}
Criterios para "accion":
- "transferir": si el cliente lo pide, dice "Operador", o ya capturaste su requerimiento de productos y debe pasar a un asesor para cotizar.
- "crear_lead": cliente NUEVO del que ya capturaste al menos Nombre y un dato de contacto (Telefono o Email).
- "actualizar_ficha": cliente EXISTENTE del que recopilaste/confirmaste datos nuevos.
- "responder": en cualquier otro caso (seguir la conversacion). Rellena en "datos" solo los campos que conozcas; deja "" los demas.`;

// Mensajes para Ollama: system + historial + mensaje actual.
const messages = [{ role: 'system', content: systemPrompt }];
for (const h of history) messages.push(h);
messages.push({ role: 'user', content: ev.message });

const ollamaBody = {
  model: $env.OLLAMA_MODEL || 'llama3.1',
  stream: false,
  format: 'json',
  options: { temperature: 0.3 },
  messages
};

return [{ json: { ...ev, existe, contactId, historyKey: key, ollamaBody } }];

// Procesa la respuesta JSON de Ollama y guarda el turno en la memoria.
const ctx = $('Contexto + memoria + prompt').item.json;
const res = $input.first().json;

let content = '';
try { content = res.message ? res.message.content : (res.content || ''); } catch (e) {}

let parsed = { respuesta: '', accion: 'responder', datos: {} };
try {
  parsed = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  // Si el modelo no devolvio JSON limpio, usa el texto como respuesta directa.
  parsed = { respuesta: String(content || 'Disculpa, no te entendi. Puedes repetirlo? 🙂'), accion: 'responder', datos: {} };
}
parsed.respuesta = parsed.respuesta || 'En un momento te ayudo. 🙂';
parsed.accion = parsed.accion || 'responder';
parsed.datos = parsed.datos || {};

// Guardar turno en memoria (recortando a los ultimos 12 mensajes).
const store = $getWorkflowStaticData('global');
const hist = Array.isArray(store[ctx.historyKey]) ? store[ctx.historyKey] : [];
hist.push({ role: 'user', content: ctx.message });
hist.push({ role: 'assistant', content: parsed.respuesta });
store[ctx.historyKey] = hist.slice(-12);

return [{ json: {
  dialogId: ctx.dialogId,
  chatId: ctx.chatId,
  existe: ctx.existe,
  contactId: ctx.contactId,
  userName: ctx.userName,
  userEmail: ctx.userEmail,
  userPhone: ctx.userPhone,
  respuesta: parsed.respuesta,
  accion: parsed.accion,
  datos: parsed.datos
} }];

